	const updateCustomer = async (id, updates) => {
		const current = data.customers.find((c) => c.id === id);
		const body = {
			...updates,
			baseVersion: current?.version ?? updates.version
		};
		try {
			await apiRequest(`/api/customers/${id}`, {
				method: "PUT",
				body
			});
			await loadRoleScopedData();
			return { success: true };
		} catch (err) {
			if (isNetworkFailure(err) && currentUser) {
				await queueOfflineOp({
					operationType: "update_customer",
					entityType: "customer",
					entityId: id,
					summaryAr: `تحديث بيانات العميل: ${current?.shopName || current?.name || id}`,
					payload: {
						customerId: id,
						...body
					}
				});
				setData((prev) => ({
					...prev,
					customers: prev.customers.map((c) => {
						if (c.id !== id) return c;
						const nextPhoto = updates.clearShopPhoto ? "" : updates.shopPhoto || updates.photo || c.shopPhoto || c.photo;
						return {
							...c,
							...updates,
							shopPhoto: nextPhoto,
							photo: nextPhoto,
							syncStatus: "pending"
						};
					})
				}));
				return {
					success: true,
					queuedOffline: true
				};
			}
			throw err;
		}
	};
