function normalizeRepProdDupText(text) {
	return String(text || "").trim().toLowerCase().replace(/[\u064B-\u065F\u0670]/g, "").replace(/[أإآ]/g, "ا").replace(/ى/g, "ي").replace(/ة/g, "ه").replace(/\s+/g, " ");
}
function checkRepLocalProductDuplicates(products, payload) {
	const bc = payload.barcode.trim().toLowerCase();
	const cd = payload.code.trim().toLowerCase();
	const normName = normalizeRepProdDupText(payload.name);
	const normCat = normalizeRepProdDupText(payload.category);
	const normUnit = normalizeRepProdDupText(payload.baseUnit);
	if (bc) {
		const byBarcode = products.find((p) => String(p.barcode || "").trim().toLowerCase() === bc || Array.isArray(p.units) && p.units.some((u) => String(u.barcode || "").trim().toLowerCase() === bc));
		if (byBarcode) return {
			exactMatch: byBarcode,
			matchedBy: "barcode",
			similarMatches: []
		};
	}
	if (cd) {
		const byCode = products.find((p) => String(p.code || "").trim().toLowerCase() === cd);
		if (byCode) return {
			exactMatch: byCode,
			matchedBy: "code",
			similarMatches: []
		};
	}
	if (normName) {
		const exactFull = products.find((p) => normalizeRepProdDupText(p.name) === normName && normalizeRepProdDupText(p.category || "") === normCat && normalizeRepProdDupText(p.baseUnit || "") === normUnit);
		if (exactFull) return {
			exactMatch: exactFull,
			matchedBy: "name_category_unit",
			similarMatches: []
		};
		return {
			exactMatch: null,
			matchedBy: null,
			similarMatches: products.filter((p) => {
				const pNorm = normalizeRepProdDupText(p.name);
				return pNorm && (pNorm === normName || pNorm.includes(normName) || normName.includes(pNorm));
			}).slice(0, 5)
		};
	}
	return {
		exactMatch: null,
		matchedBy: null,
		similarMatches: []
	};
}
